import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { format } from 'date-fns';
import { FiCheck, FiCheckCircle, FiImage, FiFile, FiDownload, FiPlay, FiPause } from 'react-icons/fi';

const AudioPlayer = ({ attachment, message }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const audioRef = useRef(null);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const updateTime = () => setCurrentTime(audio.currentTime);
    const updateDuration = () => setDuration(audio.duration);
    const handleEnd = () => setIsPlaying(false);

    audio.addEventListener('timeupdate', updateTime);
    audio.addEventListener('loadedmetadata', updateDuration);
    audio.addEventListener('ended', handleEnd);

    return () => {
      audio.removeEventListener('timeupdate', updateTime);
      audio.removeEventListener('loadedmetadata', updateDuration);
      audio.removeEventListener('ended', handleEnd);
    };
  }, []);

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio) return;

    if (isPlaying) {
      audio.pause();
    } else {
      audio.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleSeek = (e) => {
    const audio = audioRef.current;
    if (!audio) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const newTime = (clickX / rect.width) * duration;
    audio.currentTime = newTime;
    setCurrentTime(newTime);
  };

  const formatTime = (time) => {
    if (isNaN(time)) return '0:00';
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-2">
      <div className="flex items-center space-x-3 p-3 bg-gray-100 rounded-lg max-w-xs">
        <button
          onClick={togglePlay}
          className="flex-shrink-0 w-10 h-10 bg-primary-600 hover:bg-primary-700 rounded-full flex items-center justify-center transition-colors"
        >
          {isPlaying ? (
            <FiPause className="w-5 h-5 text-white" />
          ) : (
            <FiPlay className="w-5 h-5 text-white ml-1" />
          )}
        </button>
        
        <div className="flex-1 min-w-0">
          <div 
            className="w-full h-2 bg-gray-300 rounded-full cursor-pointer"
            onClick={handleSeek}
          >
            <div 
              className="h-2 bg-primary-600 rounded-full transition-all duration-100"
              style={{ width: `${duration ? (currentTime / duration) * 100 : 0}%` }}
            ></div>
          </div>
          <div className="flex justify-between text-xs text-gray-500 mt-1">
            <span>{formatTime(currentTime)}</span>
            <span>{formatTime(duration)}</span>
          </div>
        </div>
      </div>
      
      {message.content && message.content !== '🎤 Voice Message' && (
        <p className="text-sm whitespace-pre-wrap break-words">
          {message.content}
        </p>
      )}
      
      <audio
        ref={audioRef}
        src={attachment?.url || attachment?.fileUrl}
        preload="metadata"
      />
    </div>
  );
};

const MessageBubble = ({ message, isOwn, showAvatar }) => {
  const getMessageStatus = () => {
    if (message.isRead) return 'read';
    if (message.isDelivered) return 'delivered';
    return 'sent';
  };

  const formatTime = (timestamp) => {
    if (!timestamp) {
      return 'Just now';
    }
    
    try {
      const date = new Date(timestamp);
      if (isNaN(date.getTime())) {
        return 'Just now';
      }
      return format(date, 'HH:mm');
    } catch (error) {
      console.error('Error formatting timestamp:', error, 'timestamp:', timestamp);
      return 'Just now';
    }
  };

  const renderMessageContent = () => {
    // Default to text if messageType is not set or invalid
    const messageType = message.messageType || 'text';
    
    if (messageType === 'text') {
      return (
        <p className="text-sm whitespace-pre-wrap break-words">
          {message.content}
        </p>
      );
    }

    if (messageType === 'image') {
      const attachment = message.attachments?.[0];
      return (
        <div className="space-y-2">
          <img
            src={attachment?.url || attachment?.fileUrl}
            alt="Shared image"
            className="max-w-xs rounded-lg cursor-pointer hover:opacity-90 transition-opacity"
            onClick={() => window.open(attachment?.url || attachment?.fileUrl, '_blank')}
          />
          {message.content && (
            <p className="text-sm whitespace-pre-wrap break-words">
              {message.content}
            </p>
          )}
        </div>
      );
    }

    if (messageType === 'document' || messageType === 'file') {
      const attachment = message.attachments?.[0];
      const formatFileSize = (bytes) => {
        if (!bytes) return 'Unknown size';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
      };
      
      return (
        <div className="space-y-2">
          <div className="flex items-center space-x-3 p-3 bg-gray-100 rounded-lg max-w-xs">
            <div className="p-2 bg-white rounded-lg">
              {attachment?.type?.startsWith('image/') ? (
                <FiImage className="w-5 h-5 text-gray-600" />
              ) : (
                <FiFile className="w-5 h-5 text-gray-600" />
              )}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-gray-900 truncate">
                {attachment?.name || attachment?.originalName || 'File'}
              </p>
              <p className="text-xs text-gray-500">
                {formatFileSize(attachment?.size || attachment?.fileSize)}
              </p>
            </div>
            <button
              onClick={() => {
                const url = attachment?.url || attachment?.fileUrl;
                if (url) {
                  window.open(url, '_blank');
                }
              }}
              className="p-1 text-gray-500 hover:text-gray-700 transition-colors"
            >
              <FiDownload className="w-4 h-4" />
            </button>
          </div>
          {message.content && (
            <p className="text-sm whitespace-pre-wrap break-words">
              {message.content}
            </p>
          )}
        </div>
      );
    }

    if (messageType === 'audio') {
      const attachment = message.attachments?.[0];
      return (
        <AudioPlayer attachment={attachment} message={message} />
      );
    }

    return (
      <p className="text-sm text-gray-500 italic">
        Unsupported message type: {messageType}
      </p>
    );
  };

  const renderMessageStatus = () => {
    const status = getMessageStatus();
    
    if (isOwn) {
      return (
        <div className="flex items-center space-x-1 mt-1">
          <span className="text-xs text-gray-500">
            {formatTime(message.createdAt)}
          </span>
          <div className="flex items-center">
            {status === 'sent' && <FiCheck className="w-3 h-3 text-gray-400" />}
            {status === 'delivered' && <FiCheck className="w-3 h-3 text-gray-400" />}
            {status === 'read' && <FiCheckCircle className="w-3 h-3 text-blue-500" />}
          </div>
        </div>
      );
    }

    return (
      <span className="text-xs text-gray-500 mt-1">
        {formatTime(message.createdAt)}
      </span>
    );
  };

  return (
    <div className={`flex ${isOwn ? 'justify-end' : 'justify-start'} ${showAvatar ? 'mt-4' : 'mt-1'}`}>
      <div className={`flex items-end space-x-2 max-w-xs lg:max-w-md ${isOwn ? 'flex-row-reverse space-x-reverse' : ''}`}>
        {/* Avatar for other person */}
        {!isOwn && showAvatar && (
          <div className="w-8 h-8 bg-gradient-to-r from-primary-500 to-health-500 rounded-full flex items-center justify-center flex-shrink-0">
            <span className="text-white font-medium text-xs">
              {(message.sender?.fullName || message['sender.fullName'])?.charAt(0)?.toUpperCase() || 'U'}
            </span>
          </div>
        )}

        {/* Spacer when no avatar is shown for other person */}
        {!isOwn && !showAvatar && (
          <div className="w-8 h-8 flex-shrink-0"></div>
        )}

        {/* Message Bubble */}
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.2 }}
          className={`relative px-4 py-2 rounded-2xl ${
            isOwn
              ? 'bg-primary-600 text-white rounded-br-sm'
              : 'bg-gray-100 text-gray-900 rounded-bl-sm'
          }`}
        >
          {/* Message Content */}
          {renderMessageContent()}

          {/* Edited Indicator */}
          {message.isEdited && (
            <span className="text-xs opacity-70 italic">(edited)</span>
          )}

          {/* Message Status and Time */}
          <div className={`flex items-center ${isOwn ? 'justify-end' : 'justify-start'}`}>
            {renderMessageStatus()}
          </div>
        </motion.div>

        {/* Own Avatar */}
        {isOwn && showAvatar && (
          <div className="w-8 h-8 bg-gradient-to-r from-gray-500 to-gray-600 rounded-full flex items-center justify-center flex-shrink-0">
            <span className="text-white font-medium text-xs">
              {(message.sender?.fullName || message['sender.fullName'])?.charAt(0)?.toUpperCase() || 'U'}
            </span>
          </div>
        )}

        {/* Spacer when no avatar is shown for own messages */}
        {isOwn && !showAvatar && (
          <div className="w-8 h-8 flex-shrink-0"></div>
        )}
      </div>
    </div>
  );
};

export default MessageBubble;
